from datetime import datetime
from pathlib import Path
import numpy as np
from PIL import Image
r,w=map(Path,sys.argv[1:3]);sys.path.insert(0,str(w/'tools/nr-color'));import hmd_assess as h,hmd_capture as c,assess
plan=h.read_json(r/'private-plan.json');index=h.read_json(r/'campaign-index.json')
assert h.digest(r/'private-plan.json')==index['planSha256']
raw=h.read_json(r/'campaign-record-stop.json');record=json.loads(raw['content'][0]['text'])
assert record['meta']['correlationId'].startswith('nr-hmd-brighter-restart-')
physical=Path('D:/Skyrim Mods/mods/Synthesis Patch (SFW)/SKSE/Plugins/devbench/recordings')/Path(record['path']).name
record['artifacts']=[h.preserve(physical,r/'recordings/campaign.json')]
recording=h.read_json(physical);scene=h.recording_scene(recording,plan)
assert not record['limitReached'] and record['unrecordedTailMs']==0
entries=[];sequences=[];camera_diagnostics=[];errors=[]
for core in sorted((r/'steps').glob('*/entry-core.json')):
 e=h.read_json(core);n=e['scheduleOrdinal'];step=plan['schedule'][n-1];candidate=plan['candidateMapping'][step['candidateId']]
 e['recording']=copy.deepcopy(record);e['userSessionAuthorization']=h.read_json(r/'user-session-authorization.json')
 dp=core.parent/'capture-diagnostics.json';e['captureDiagnosticsArtifact']={'path':str(dp),'bytes':dp.stat().st_size,'sha256':h.digest(dp)}
 m=h.read_json(h.committed(e['manifest'],r));assert m['producer']==index['producer'] and m['sessionId']==index['sessionId']
 assert m['state']=='final' and m['counts']['inFlight']==0
 assert datetime.fromisoformat(m['acceptedUtc'].replace('Z','+00:00'))>=datetime.fromisoformat(plan['createdUtc'])
 assert m['counts']['requested']>=step['minimumPairs'] and len(m['children'])==m['counts']['scheduled']
 assert set(ch['ordinal'] for ch in m['children'])==set(range(1,len(m['children'])+1))
 assert len({ch['requestId'] for ch in m['children']})==len(m['children'])
 h.check_capture_descriptor(m['requested']);h.check_capture_descriptor(m['effective'])
 pairs=[];rejected=[]
 for ch in m['children']:
  try:
   pair=h.check_pair(ch,Path(e['manifest']['path']).parent,e['expected'],candidate,plan['regionPolicy'],capture_diagnostics=e['captureDiagnostics'],sequence=m)
   acq=pair['acquisition'];cam=acq['cameraEvidence']
   assert not pairs or acq['monotonicTimestampUs']>pairs[-1]['acquisition']['monotonicTimestampUs']
   assert not pairs or acq['compositorCycle']!=pairs[-1]['acquisition']['compositorCycle']
   assert cam['available'] and cam['provenance']=='engine_cached_unjittered_world_matrices'
   assert cam['sourceWorldFrame']==acq['nrEvidence']['left']['sourceWorldFrame']
   row={'scheduleOrdinal':n,'ordinal':ch['ordinal']}
   for key in ['view','projection','positionAdjust']:row[key]=float(np.max(np.abs(np.array(cam[key])-np.array(plan['fixedScene']['cameraEvidence'][key]))))
   try:h.check_camera(acq,plan['fixedScene']);row['strictCameraPassed']=True
   except Exception as ex:row.update(strictCameraPassed=False,strictCameraReason=str(ex))
   camera_diagnostics.append(row);pairs.append(pair)
  except Exception as ex:rejected.append({'ordinal':ch['ordinal'],'error':str(ex)})
 e.update(validatedPairs=len(pairs),excludedChildren=rejected,motionEvidence=c.acquisition_motion(pairs,plan),recordedScene=scene)
 if len(pairs)<12:e['error']='Insufficient frame-attributed pairs';errors.append({'scheduleOrdinal':n,'rejected':rejected})
 h.save_json(core.parent/'entry.json',e);entries.append(e)
 if len(pairs)>=12 and scene['qualified']:sequences.append({**step,'pairs':pairs,'expected':e['expected'],'motionEvidence':e['motionEvidence'],'captureDiagnostics':e['captureDiagnostics']})
scope=h.read_json(r/'comparison-scope.json');selected=set(scope['selectedOrdinals']);seen={e['scheduleOrdinal'] for e in entries}
for previous,current in zip(sequences,sequences[1:]):assert current['pairs'][0]['acquisition']['monotonicTimestampUs']>previous['pairs'][-1]['acquisition']['monotonicTimestampUs']
for n in range(1,len(plan['schedule'])+1):
 if n not in seen:entries.append({'scheduleOrdinal':n,'notRunReason':'Not selected in the frozen bounded exploratory scope.' if n not in selected else 'Selected capture did not complete; preserved failure receipt identifies the reason.'})
index.update(sequences=sorted(entries,key=lambda e:e['scheduleOrdinal']),complete=False,exploratoryCaptureComplete=seen==selected,protocolQualified=False,terminalReason='User-authorized bounded comparison; strict camera and gradient findings retained as diagnostics.')
h.preserve(r/'campaign-index.json',r/'campaign-index-before-finalization.json');assess.atomic_json(r/'campaign-index.json',index)
h.save_json(r/'camera-diagnostics.json',camera_diagnostics);h.save_json(r/'attribution-errors.json',errors);h.save_json(r/'recorded-scene-check.json',scene)
bases=[e for e in entries if e['scheduleOrdinal'] in [1,2,3] and 'manifest' in e]
if len(bases)==3:h.save_json(r/'baseline-repeatability-gate.json',c.baseline_repeatability(bases,plan))
out=r/'exploratory-analysis';out.mkdir();(out/'private').mkdir()
h.prepare_anonymous(sequences,plan['regionPolicy'],out,plan['seed'])
rows,temporal,stereo,repeats=h.measure_sequences(sequences,plan['regionPolicy'],out)
for name,items in [('regions',rows),('temporal',temporal),('stereo',stereo),('strict-filtered-sequence-repeatability',repeats),('exposure',h.exposure_measurements(sequences))]:
 h.save_json(out/'private'/(name+'.json'),items);h.write_csv(out/'private'/(name+'.csv'),items)
h.save_json(out/'private/sequence-mapping.json',[{k:s[k] for k in ['anonymousId','candidateId','scheduleOrdinal','repetition','direction','role','block']} for s in sequences])
metrics=['mean_r','mean_g','mean_b','luma_mean','luma_p05','luma_p95','local_contrast','edge_rms','clipped_black_fraction','clipped_white_fraction']
aggregate=[]
for key in sorted({(x['scheduleOrdinal'],x['eye'],x['region']) for x in rows}):
 sample=[x for x in rows if (x['scheduleOrdinal'],x['eye'],x['region'])==key];s=sample[0];candidate=plan['candidateMapping'][s['candidateId']]
 item={k:s[k] for k in ['scheduleOrdinal','candidateId','anonymousId','direction','role','eye','region']}
 item.update(condition=candidate['condition'],sourceCondition=candidate.get('sourceCondition',candidate['condition']),strictGradientFlagged=sum(x['motionConfounded'] for x in sample),frames=len(sample))
 for metric in metrics:item[metric]=float(np.mean([x[metric] for x in sample]))
 aggregate.append(item)
envelopes=[]
for eye,region in sorted({(x['eye'],x['region']) for x in aggregate}):
 bases=[x for x in aggregate if x['role']=='baseline' and x['eye']==eye and x['region']==region]
 envelope={'eye':eye,'region':region,'baselineSequences':len(bases)}
 for metric in metrics:
  vals=[x[metric] for x in bases];envelope[metric]={'min':min(vals),'max':max(vals),'span':max(vals)-min(vals),'mean':float(np.mean(vals))}
 envelopes.append(envelope)
contrasts=[]
for shown_id,candidate in plan['candidateMapping'].items():
 if 'hiddenCandidateId' not in candidate:continue
 for direction in ['forward','reverse']:
  for eye,region in sorted({(x['eye'],x['region']) for x in aggregate}):
   shown=[x for x in aggregate if x['candidateId']==shown_id and x['direction']==direction and x['eye']==eye and x['region']==region]
   hidden=[x for x in aggregate if x['candidateId']==candidate['hiddenCandidateId'] and x['direction']==direction and x['eye']==eye and x['region']==region]
   if len(shown)!=1 or len(hidden)!=1:continue
   env=next(e for e in envelopes if e['eye']==eye and e['region']==region)
   contrasts.append({'condition':candidate['condition'],'direction':direction,'eye':eye,'region':region,'shownSequence':shown[0]['anonymousId'],'hiddenSequence':hidden[0]['anonymousId'],'shownOrdinal':shown[0]['scheduleOrdinal'],'hiddenOrdinal':hidden[0]['scheduleOrdinal'],'delta':{m:shown[0][m]-hidden[0][m] for m in metrics},'baselineSpan':{m:env[m]['span'] for m in metrics}})
h.save_json(out/'private/all-frame-sequence-means.json',aggregate);h.save_json(out/'private/all-frame-baseline-envelopes.json',envelopes);h.save_json(out/'private/shown-hidden-contrasts.json',contrasts)
review=out/'review';manifest=[]
for s in sequences:
 frames=[]
 for pair in s['pairs']:
  if pair['ordinal'] not in [1,6,12]:continue
  for eye in h.EYES:
   original=Path(pair['images'][eye]['anonymousPath']);im=Image.open(original);crops=[]
   for region in plan['regionPolicy']['eyes'][eye]['regions']:
    x,y,ww,hh=region['rect'];name=s['anonymousId']+f"-f{pair['ordinal']:02}-{eye}-"+region['id'];dest=review/'sampled-crops'/(name+'.png');dest.parent.mkdir(parents=True,exist_ok=True);im.crop((x,y,x+ww,y+hh)).save(dest);crops.append({'region':region['id'],'class':region['class'],'path':str(dest)})
   dest=review/'overviews'/(s['anonymousId']+f"-f{pair['ordinal']:02}-{eye}.png");dest.parent.mkdir(parents=True,exist_ok=True);im.thumbnail((740,822));im.save(dest)
   frames.append({'ordinal':pair['ordinal'],'eye':eye,'timestampUtc':pair['acquisition']['utcTimestamp'],'original':str(original),'overview':str(dest),'crops':crops})
 manifest.append({'sequenceId':s['anonymousId'],'sourceReference':s['role']=='baseline','frames':frames})
h.save_json(review/'images.json',manifest)
references=[s['anonymousId'] for s in sequences if s['role']=='baseline']
requests=[]
for shown_id,candidate in plan['candidateMapping'].items():
 if 'hiddenCandidateId' not in candidate:continue
 group=[]
 for direction in ['forward','reverse']:
  shown=[s for s in sequences if s['candidateId']==shown_id and s['direction']==direction];hidden=[s for s in sequences if s['candidateId']==candidate['hiddenCandidateId'] and s['direction']==direction]
  if len(shown)==1 and len(hidden)==1:group.append({'first':shown[0]['anonymousId'],'second':hidden[0]['anonymousId'],'order':'first_then_second' if shown[0]['scheduleOrdinal']<hidden[0]['scheduleOrdinal'] else 'second_then_first'})
 if group:requests.append({'comparisonId':'P'+str(len(requests)+1),'repeats':group,'sourceReferences':references})
random.Random(plan['seed']).shuffle(requests)
h.save_json(review/'comparisons.json',requests)
(review/'review-prompt.md').write_text((w/'tools/nr-color/hmd-review.prompt.md').read_text())
summary={'eligibleSequences':len(sequences),'attributionErrors':errors,'selectedCaptureComplete':seen==selected,'strictCameraFailedPairs':sum(not x['strictCameraPassed'] for x in camera_diagnostics),'cameraMax':{key:max(x[key] for x in camera_diagnostics) for key in ['view','projection','positionAdjust']},'strictGradientFlaggedRows':sum(x['motionConfounded'] for x in rows),'measuredRows':len(rows),'samplingUsMin':min(x['spacingUs'] for x in temporal),'samplingUsMax':max(x['spacingUs'] for x in temporal),'recordingSceneQualified':scene['qualified'],'menuAndLifecycleEvents':[x for x in recording.get('activityEvents',[]) if x.get('kind') in ['menu','cell','lifecycle']],'recordedMs':record['recordedMs'],'reviewSequences':len(manifest),'comparisons':len(requests),'protocolQualified':False,'interpretation':'All-frame regional means are exploratory and retain flagged frames; source variation and blinded original-pixel observations constrain conclusions. No registration or normalization.'}
h.save_json(r/'comparison-summary.json',summary);print(json.dumps(summary))

import json,sys,numpy as np
from pathlib import Path
r=Path(sys.argv[1]);p=lambda f:json.loads(f.read_text());idx=p(r/'campaign-index.json');events=p(r/'comparison-summary.json')['menuAndLifecycleEvents'];seqs={};flags=[]
for e in idx['sequences']:
 if 'manifest' not in e:continue
 m=p(Path(e['manifest']['path']));children=m['children'];cams=[x['actual']['acquisition']['cameraEvidence'] for x in children]
 seqs[e['scheduleOrdinal']]={'mean':{k:np.mean([x[k] for x in cams],axis=0) for k in ['view','projection','positionAdjust']},'firstFrame':children[0]['actual']['acquisition']['engineFrame'],'lastFrame':children[-1]['actual']['acquisition']['engineFrame']}
 for ch in children:
  frame=ch['actual']['acquisition']['engineFrame'];journal=False
  for ev in events:
   if ev['name']=='Journal Menu' and ev['frame']<=frame:journal=ev['opening']
  if journal:flags.append({'scheduleOrdinal':e['scheduleOrdinal'],'ordinal':ch['ordinal'],'frame':frame})
contrasts=p(r/'exploratory-analysis/private/shown-hidden-contrasts.json')
pairCam={}
for x in contrasts:
 key=f"{x['shownOrdinal']}:{x['hiddenOrdinal']}"
 if key not in pairCam:
  a,b=seqs[x['shownOrdinal']],seqs[x['hiddenOrdinal']]
  pairCam[key]={'condition':x['condition'],'direction':x['direction'],'cameraMeanDifference':{k:float(np.max(np.abs(a['mean'][k]-b['mean'][k]))) for k in a['mean']}}
baseline=[]
agg=p(r/'exploratory-analysis/private/all-frame-sequence-means.json')
for x in agg:
 if x['role']=='baseline' and x['region'] in ['face','forehead']:baseline.append({k:x[k] for k in ['scheduleOrdinal','eye','region','luma_mean','mean_r','mean_g','mean_b']})
out={'journalOverlappingPairs':flags,'sequenceFrameRanges':{str(k):{kk:vv for kk,vv in v.items() if kk!='mean'} for k,v in seqs.items()},'pairedCamera':pairCam,'baselineMeans':baseline}
(r/'confound-audit.json').write_text(json.dumps(out,indent=2));print(json.dumps(out))

