from pathlib import Path
from PIL import Image
r,w=map(Path,sys.argv[1:3]);stage=sys.argv[3];sys.path.insert(0,str(w/'tools/nr-color'));import hmd_assess as h
plan=h.read_json(r/'private-plan.json');selected=h.read_json(r/'comparison-scope.json')['selectedOrdinals'];ids=list(range(len(selected)));random.Random(plan['seed']^0xA16709).shuffle(ids);names={n:f'Q{ids[i]+1:04}' for i,n in enumerate(selected)}
out=r/'blind-review';out.mkdir(exist_ok=True)
if not (out/'review-prompt.md').exists():shutil.copy2(w/'tools/nr-color/hmd-review.prompt.md',out/'review-prompt.md')
sources=[1,2,3] if stage=='1' else [14,25]
available={}
for n in selected:
 core=r/f'steps/{n:03}/entry-core.json'
 if not core.exists():continue
 entry=h.read_json(core);manifest=h.read_json(h.committed(entry['manifest'],r));frames=[]
 for child in manifest['children']:
  if child['ordinal'] not in [1,6,12]:continue
  pair=h.check_pair(child,Path(entry['manifest']['path']).parent,entry['expected'],plan['candidateMapping'][plan['schedule'][n-1]['candidateId']],plan['regionPolicy'],capture_diagnostics=entry['captureDiagnostics'],sequence=manifest)
  for eye in h.EYES:
   imagePath=Path(pair['images'][eye]['path']);im=Image.open(imagePath);original=out/'originals'/f"{names[n]}-f{child['ordinal']:02}-{eye}.png"
   if not original.exists():h.preserve(imagePath,original)
   overview=out/'overviews'/original.name;overview.parent.mkdir(parents=True,exist_ok=True);crop_items=[]
   for region in plan['regionPolicy']['eyes'][eye]['regions']:
    rect=region['rect'];path=out/'crops'/f"{names[n]}-f{child['ordinal']:02}-{eye}-{region['id']}.png";path.parent.mkdir(parents=True,exist_ok=True)
    if not path.exists():im.crop((rect[0],rect[1],rect[0]+rect[2],rect[1]+rect[3])).save(path)
    crop_items.append({'region':region['id'],'class':region['class'],'path':str(path)})
   if not overview.exists():im.thumbnail((740,822));im.save(overview)
   frames.append({'ordinal':child['ordinal'],'eye':eye,'timestampUtc':pair['acquisition']['utcTimestamp'],'original':str(original),'overview':str(overview),'crops':crop_items})
  im.close()
 available[n]={'sequenceId':names[n],'sourceReference':plan['schedule'][n-1]['role']=='baseline','frames':frames}
groups=[(5,6,23,22),(8,9,20,19),(11,12,17,16)]
for k,(a,b,aa,bb) in enumerate(groups,1):
 pair=(a,b) if stage=='1' else (aa,bb);need=[*sources,*pair]
 if not all(n in available for n in need):continue
 payload={'comparisonId':f'P{k}','stage':int(stage),'first':names[pair[0]],'second':names[pair[1]],'acquisitionOrder':'first_then_second' if pair[0]<pair[1] else 'second_then_first','sourceReferences':[names[n] for n in sources],'sequences':[available[n] for n in need],'instructions':'Compare first and second to each other and to each eye own source references. Account for source variation; no normalization, mapping guesses or model-contract inference.'}
 h.save_json(out/f'stage{stage}-P{k}.json',payload)
print(json.dumps({'stage':stage,'preparedSequences':len(available),'requests':[str(p) for p in out.glob('stage'+stage+'-P*.json')]}))

